const $ = s => document.querySelector(s);
let currentView='dashboard';
let currentRole=localStorage.getItem('salus_role')||'Assessment Director';
let currentUser=localStorage.getItem('salus_user')||'Local Operator';
let activeAssessmentId=Number(localStorage.getItem('salus_assessment_id')||0);
let validatingImprovementId=null;
let overridingThreatId=null;
let editingRecord=null;
let systemMode={auth_mode:'prototype',version:'2.2.0',restore_enabled:false};
let accessState=null;
let workspaceState=null;
let copDecisionRequests=[];
const PRODUCT_TERMS=window.SalusProductTerms||{salcapa:{name:'SalCAPA™'},salintel:{name:'SalINTEL™'},salthira:{name:'SalTHIRA™'},salops:{name:'SalOPS™'}};
const viewTitles={dashboard:`${PRODUCT_TERMS.salcapa.name} Command Center`,common_operating_picture:`${PRODUCT_TERMS.salcapa.name} Common Operating Picture`,salintel:`${PRODUCT_TERMS.salintel.name} Intelligence Overview`,salintel_domains:`${PRODUCT_TERMS.salintel.name} Type of Investigation`,assessments:`${PRODUCT_TERMS.salthira.name} Risk Assessments`,salthira:`${PRODUCT_TERMS.salthira.name} Risk Assessments`,salops:`${PRODUCT_TERMS.salops.name} Operations & Requests`,reports:`${PRODUCT_TERMS.salcapa.name} Reports`};
const subtitles={dashboard:'Coordinate decisions, assignments, approvals, and action.',common_operating_picture:'See what is happening, what matters, and what has changed.',risk:'Calculated risk remains intact while accountable professional judgment is recorded separately.',priorities:'Transparent improvement ranking across consequence reduction, mission benefit, feasibility, sustainability, compliance, staffing, cost, and time.',reassessment:'Event-driven reassessment triggers from intelligence, incidents, exercises, changes, and completed improvements.',assessments:'Controlled workspaces for each THIRA engagement.',threats:'Evidence-based threats and hazards, screened and traceable.',scenarios:'Credible operating conditions, consequences, assumptions, and decisions.',capabilities:'Required outcomes measured against demonstrated performance.',evidence:'Controlled evidence with verification, validity, lifecycle review, and stale-evidence reassessment.',gaps:'Required capability versus demonstrated capability.',improvements:'Competing improvement alternatives, costs, and expected benefit.',decisions:'Approve, defer, reject, transfer, monitor, or accept risk.',accepted_risks:'Accepted risk remains active, owned, reviewable, and traceable until formally closed or superseded.',implementation:'Track approved actions through completion, evidence-based validation, and closure.',reports:'Executive reports preserved from authoritative assessment records.',trace:'Trace each finding from mission through decision.',attachments:'Controlled evidence attachments with file integrity hashes.',governance:'Workflow transitions, scope-change approvals, assessment versions, and revision history.',audit:'Governed activity and version history.',backups:'Integrity-verified backup packages, recovery controls, and restore safeguards.',security:'Operational readiness, security events, identity, storage, and protection controls.',salintel_domains:'Investigate, qualify, and govern knowledge across SalINTEL domains.',configuration:'Industry profiles, assessment weighting, and role-aware access.'};

function authHeaders(){return ['session','oidc'].includes(systemMode.auth_mode)?{}:{'X-Salus-Role':currentRole,'X-Salus-User':currentUser,'X-Salus-Tenant':'1'}}
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...authHeaders(),...(opts.headers||{})},...opts}); if(!r.ok) throw new Error(await r.text()); return r.json();}
async function getActiveAssessment(){const rows=await api('/api/assessments'); if(!rows.length)return null; let a=rows.find(x=>x.id===activeAssessmentId); if(!a){a=rows[0];activeAssessmentId=a.id;localStorage.setItem('salus_assessment_id',String(a.id));} return a;}
function scopedUrl(key){return key==='assessments'||!activeAssessmentId?'/api/'+key:`/api/${key}?assessment_id=${activeAssessmentId}`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function fmtMoney(v){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(v||0))}
function badge(v){return `<span class="badge ${String(v||'').toLowerCase()}">${esc(v)}</span>`}
function setView(v){
  currentView=v;
  const buttons=[...document.querySelectorAll('#nav button')];
  buttons.forEach(b=>b.classList.toggle('active',b.dataset.view===v));
  const activeButton=buttons.find(b=>b.dataset.view===v);
  const workAreaDisclosure=activeButton?.closest('details.nav-work-areas');
  if(workAreaDisclosure) workAreaDisclosure.open=true;
  $('#page-title').textContent=viewTitles[v]||v.replace(/\b\w/g,c=>c.toUpperCase());
  $('#page-subtitle').textContent=subtitles[v]||'';
  render();
}
[...document.querySelectorAll('#nav button')].forEach(b=>b.onclick=()=>setView(b.dataset.view));
function isProtectedMember(){return workspaceState?.experience==='Protected Member';}
function applyWorkspaceNavigation(){
  const protectedMember=isProtectedMember();
  document.querySelectorAll('#nav [data-salus-only="true"]').forEach(item=>{ item.hidden=protectedMember; });
}

async function render(){try{if(currentView==='dashboard'||currentView==='common_operating_picture') return dashboard(); if(currentView==='salintel') return salintel(); if(currentView==='salintel_domains') return salintelDomains(); if(currentView==='salops') return salops(); if(currentView==='salthira') return entityView('assessments'); if(currentView==='risk') return riskAnalytics(); if(currentView==='priorities') return prioritization(); if(currentView==='reassessment') return entityView('reassessment_triggers'); if(currentView==='trace') return trace(); if(currentView==='attachments') return attachments(); if(currentView==='governance') return governance(); if(currentView==='audit') return audit(); if(currentView==='backups') return backups(); if(currentView==='security') return securityReadiness(); if(currentView==='implementation') return implementation(); if(currentView==='reports') return reports(); if(currentView==='configuration') return configuration(); return entityView(currentView);}catch(e){$('#content').innerHTML=`<div class="notice"><strong>Error</strong><br>${esc(e.message)}</div>`}}

async function dashboard(){
  const d=await api('/api/salcapa/common-operating-picture'),m=d.metrics,w=d.workspace,readiness=d.protective_readiness,see=d.see,threads=d.coordinate.threads,requests=d.act.decision_requests;copDecisionRequests=requests;
  workspaceState=w;applyWorkspaceNavigation();
  const isCop=currentView==='common_operating_picture';
  const canWrite=(accessState?.permissions||[]).includes('write'),memberAuthority=w.role==='Client Executive',salus=!isProtectedMember()&&w.role!=='Auditor';
  const intelligence=see.intelligence.map(x=>[esc(x.title),badge(x.credibility),esc(x.operational_significance),badge(x.status)]);
  const alerts=see.alerts.map(x=>[esc(x.title),badge(x.priority),badge(x.status),esc(x.due_at)]);
  const operations=[...see.operations.map(x=>[esc(x.title),badge(x.priority),badge(x.status),esc(x.result_summary)]),...see.engagements.map(x=>[esc(x.title),badge(x.service_type),badge(x.status),esc(x.member_status_summary)])];
  const risks=see.accepted_risks.map(x=>[esc(x.title),esc(x.residual_exposure),badge(x.status),esc(x.review_date)]);
  const threadCards=threads.map(t=>`<article class="card coordination-thread"><div class="section-title"><div><h3>${esc(t.subject)}</h3><span class="subtle">${badge(t.status)} ${t.assigned_contact?`· ${esc(t.assigned_contact_summary||t.assigned_contact)}`:'· Awaiting Salus assignment'}</span></div><div class="row-actions">${t.status==='Open'&&canWrite?`<button class="btn secondary" onclick="addCopMessage(${t.id})">Reply</button>`:''}${t.status==='Open'&&salus?`<button class="btn secondary" onclick="assignCopThread(${t.id})">Assign</button><button class="btn secondary" onclick="closeCopThread(${t.id})">Close</button>`:''}</div></div><div class="message-list">${t.messages.map(msg=>`<div class="message ${msg.author_role==='Client Executive'||msg.author_role==='Contributor'?'member':'salus'}"><strong>${esc(msg.author)}</strong><span>${esc(msg.author_role)} · ${esc(msg.created_at)}</span><p>${esc(msg.body)}</p>${msg.audience==='Internal'?'<em>Internal</em>':''}</div>`).join('')}</div></article>`).join('');
  const readinessCards=(readiness?.stages||[]).map((stage,index)=>`<article class="readiness-stage ${esc(stage.key)}"><span>${index+1}</span><div><h3>${esc(stage.label)}</h3><p>${esc(stage.description)}</p></div><strong>${stage.count}</strong></article>`).join('');
  const actionRows=requests.map(x=>[esc(x.action_type),esc(x.title),esc(x.member_summary),esc(x.due_at),badge(x.status),x.status==='Awaiting Decision'&&memberAuthority?`<button class="btn" onclick="decideCopRequest(${x.id})">Decide</button>`:x.status==='Awaiting Decision'&&salus?`<button class="btn secondary" onclick="withdrawCopRequest(${x.id})">Withdraw</button>`:esc(x.decision||'Awaiting authority')]);

  const situation=`
    <div class="card cop-hero"><span>Common Operating Picture · See and understand</span><h2>What is happening now</h2><p>${esc(readiness?.promise||"See what matters, what has changed, and what may need attention.")}</p></div>
    <section class="readiness-overview"><div class="section-title"><div><h2>Protective work at a glance</h2><p class="subtle">This view reflects saved work and evidence. It is not a self-reported score.</p></div></div><div class="readiness-path">${readinessCards}</div></section>
    <div class="grid stats cop-stats">${metric('Qualified Intelligence',m.qualified_intelligence)}${metric('Needs Attention',m.priority_actions)}${metric('Decisions Waiting',m.pending_member_decisions)}${metric('Active Operations',m.active_operations)}</div>
    <section class="page-section"><div class="section-title"><div><h2>Understand the Situation</h2><p class="subtle">Use trusted information to see what matters now.</p></div></div>
      <div class="two-col grid"><div><div class="section-title"><h3>Intelligence</h3><span class="component intel">SalINTEL</span></div>${table(['Finding','Credibility','Why it matters','Status'],intelligence)}</div><div><div class="section-title"><h3>Assessment priorities</h3><span class="component thira">SalTHIRA</span></div>${table(['Condition','Priority','Status','Due'],alerts)}</div></div>
      <div class="two-col grid"><div><div class="section-title"><h3>Operations and requests</h3><span class="component ops">SalOPS</span></div>${table(['Work','Priority or service','Status','Member summary'],operations)}</div><div><div class="section-title"><h3>Accepted risk</h3><span class="subtle">Protected Member review</span></div>${table(['Risk','What remains','Status','Review'],risks)}</div></div>
      <div class="section-title"><h3>Released work and observations</h3></div>${table(['Type','Reference','Status','Updated'],[...see.deliverables.map(x=>[esc(x.report_type),`Assessment #${x.assessment_id}`,badge(x.status),esc(x.released_at)]),...see.observations.map(x=>['Observation',esc(x.record_key),badge(x.status),esc(x.updated_at)])])}
    </section>
    <section class="workspace-handoff"><div><h2>Does something need action?</h2><p>Move to the Command Center to coordinate decisions, assignments, and approvals.</p></div><button class="action-link" onclick="setView('dashboard')">Coordinate action &gt;</button></section>`;

  const primaryAction=salus?'<button class="btn" onclick="createCopDecisionRequest()">Issue decision request</button>':'';
  const coordinateForm=canWrite?`<details class="card progressive-panel"><summary>Start a new coordination thread</summary><form id="cop-thread-form"><div class="form-grid"><label>Subject<input name="subject" maxlength="500" required></label><label>Assessment, if needed<input name="assessment_id" type="number" min="1" value="${activeAssessmentId||''}"></label></div><label>Message<textarea name="message" maxlength="12000" required></textarea></label><div class="form-actions"><button class="btn">Start coordination</button></div></form></details>`:'';
  const command=`
    <div class="card cop-hero"><span>Command Center · Coordinate and act</span><h2>Work that needs attention</h2><p>See what needs a decision, who owns the work, and what happens next.</p></div>
    <div class="grid stats command-stats">${metric('Needs Attention',m.priority_actions)}${metric('Decisions Waiting',m.pending_member_decisions)}${metric('Active Operations',m.active_operations)}</div>
    <section class="page-section"><div class="stage-heading"><span>1</span><div><h2>Needs Your Attention</h2><p>Decisions and requests that need an authorized person.</p></div>${primaryAction}</div>${table(['Decision type','Subject','Why it matters','Due','Status','Next step'],actionRows)}</section>
    <section class="page-section"><div class="stage-heading"><span>2</span><div><h2>Current Work</h2><p>Open coordination, ownership, messages, and next steps.</p></div></div>${coordinateForm}<div class="thread-grid">${threadCards||'<div class="card subtle">No coordination work is open.</div>'}</div></section>
    <section class="workspace-handoff"><div><h2>Need the facts behind the work?</h2><p>Return to the Common Operating Picture to see what is happening and why it matters.</p></div><button class="action-link" onclick="setView('common_operating_picture')">View the situation &gt;</button></section>`;

  $('#content').innerHTML=isCop?situation:command;
  const form=$('#cop-thread-form');if(form)form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),assessment=fd.get('assessment_id');await api('/api/salcapa/coordination/threads',{method:'POST',body:JSON.stringify({subject:fd.get('subject'),message:fd.get('message'),assessment_id:assessment?Number(assessment):null})});render();};
}
function metric(label,value){return `<div class="card metric"><span>${label}</span><strong>${value}</strong></div>`}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="subtle">No records yet.</td></tr>`}</tbody></table>`}
async function addCopMessage(id){const body=prompt('Shared message:');if(!body)return;await api(`/api/salcapa/coordination/threads/${id}/messages`,{method:'POST',body:JSON.stringify({body,audience:'Shared'})});render();}
async function assignCopThread(id){const assigned_contact=prompt('Assigned Salus contact:');if(!assigned_contact)return;const member_contact_summary=prompt('Member-facing contact information:');if(!member_contact_summary)return;await api(`/api/salcapa/coordination/threads/${id}/assign`,{method:'POST',body:JSON.stringify({assigned_contact,member_contact_summary})});render();}
async function closeCopThread(id){const reason=prompt('Closure basis:');if(!reason)return;await api(`/api/salcapa/coordination/threads/${id}/close`,{method:'POST',body:JSON.stringify({reason})});render();}
async function createCopDecisionRequest(){const source_type=prompt('Source type: intel_finding, reassessment_trigger, improvement, accepted_risk, ops_request, or ops_estimate');if(!source_type)return;const source_id=Number(prompt('Source record ID:'));if(!source_id)return;const action_type=prompt('Decision type: Set Priority, Approve Recommendation, Authorize Resources, Risk Decision, or Request Action');if(!action_type)return;const title=prompt('Decision title:');if(!title)return;const member_summary=prompt('Member-facing decision context:');if(!member_summary)return;const due_at=prompt('Due time (ISO 8601, optional):')||'';await api('/api/salcapa/decision-requests',{method:'POST',body:JSON.stringify({source_type,source_id,action_type,title,member_summary,due_at})});render();}
async function decideCopRequest(id){const item=copDecisionRequests.find(x=>x.id===id);if(!item)return;const decision=prompt(`Choose one: ${item.allowed_choices.join(', ')}`);if(!decision)return;const rationale=prompt('Decision rationale:');if(!rationale)return;const conditions=decision.includes('Conditions')?(prompt('Decision conditions:')||''):'';const authorized_amount=item.action_type==='Authorize Resources'&&decision.startsWith('Authorize')?Number(prompt('Authorized amount (USD):','0')||0):0;await api(`/api/salcapa/decision-requests/${item.id}/decide`,{method:'POST',body:JSON.stringify({decision,rationale,conditions,authorized_amount})});render();}
async function withdrawCopRequest(id){const reason=prompt('Withdrawal reason:');if(!reason)return;await api(`/api/salcapa/decision-requests/${id}/withdraw`,{method:'POST',body:JSON.stringify({reason})});render();}

